#include <bits/stdc++.h>
using namespace std;

// Decodes one JSON string literal into Unicode code points (surrogate pairs combined).
vector<uint32_t> decode(const string &s) {
    vector<uint32_t> cps;
    size_t i = s.find('"') + 1;
    auto hex4 = [&](size_t at) { return (uint32_t)stoul(s.substr(at, 4), nullptr, 16); };
    while (s[i] != '"') {
        unsigned char c = s[i];
        if (c == '\\') {
            char e = s[i + 1];
            i += 2;
            if (e != 'u') {
                const string from = "\"\\/bfnrt", to = "\"\\/\b\f\n\r\t";
                cps.push_back((unsigned char)to[from.find(e)]);
                continue;
            }
            uint32_t u = hex4(i);
            i += 4;
            if (u >= 0xD800 && u < 0xDC00 && s.compare(i, 2, "\\u") == 0) {
                uint32_t low = hex4(i + 2);
                if (low >= 0xDC00 && low < 0xE000) {
                    u = 0x10000 + ((u - 0xD800) << 10) + (low - 0xDC00);
                    i += 6;
                }
            }
            cps.push_back(u);
        } else if (c < 0x80) {
            cps.push_back(c), i++;
        } else {
            int extra = c >= 0xF0 ? 3 : c >= 0xE0 ? 2 : 1;
            uint32_t cp = c & (0x3F >> extra);
            for (int k = 1; k <= extra; k++) cp = (cp << 6) | (s[i + k] & 0x3F);
            cps.push_back(cp), i += extra + 1;
        }
    }
    return cps;
}

// Encodes like Python json.dumps(..., ensure_ascii=True).
string encode(const vector<uint32_t> &cps) {
    string out = "\"";
    char hex[8];
    auto unit = [&](uint32_t u) { snprintf(hex, sizeof hex, "\\u%04x", u), out += hex; };
    for (uint32_t c : cps) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else if (c == '\b') out += "\\b";
        else if (c == '\f') out += "\\f";
        else if (c >= 0x20 && c <= 0x7E) out += (char)c;
        else if (c < 0x10000) unit(c);
        else unit(0xD800 + ((c - 0x10000) >> 10)), unit(0xDC00 + ((c - 0x10000) & 0x3FF));
    }
    return out + "\"";
}

int main() {
    string raw((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    vector<uint32_t> s = decode(raw);
    size_t n = s.size();
    cout << encode({s[n - 1], ' ', s[n - 2]}) << "\n";
}

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
    // Decodes one JSON string literal; \\u escapes give UTF-16 units, so surrogate pairs combine.
    static String decode(String s) {
        StringBuilder sb = new StringBuilder();
        int i = s.indexOf('"') + 1;
        while (s.charAt(i) != '"') {
            char c = s.charAt(i);
            if (c != '\\') {
                sb.append(c);
                i++;
                continue;
            }
            char e = s.charAt(i + 1);
            i += 2;
            if (e == 'u') {
                sb.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
                i += 4;
            } else {
                sb.append("\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e)));
            }
        }
        return sb.toString();
    }

    static void unit(StringBuilder out, int u) {
        out.append("\\u").append(String.format("%04x", u));
    }

    // Encodes like Python json.dumps(..., ensure_ascii=True).
    static String encode(int[] cps) {
        StringBuilder out = new StringBuilder("\"");
        for (int c : cps) {
            if (c == '"') out.append("\\\"");
            else if (c == '\\') out.append("\\\\");
            else if (c == '\n') out.append("\\n");
            else if (c == '\r') out.append("\\r");
            else if (c == '\t') out.append("\\t");
            else if (c == '\b') out.append("\\b");
            else if (c == '\f') out.append("\\f");
            else if (c >= 0x20 && c <= 0x7E) out.append((char) c);
            else if (c < 0x10000) unit(out, c);
            else {
                unit(out, Character.highSurrogate(c));
                unit(out, Character.lowSurrogate(c));
            }
        }
        return out.append('"').toString();
    }

    public static void main(String[] args) throws IOException {
        String raw = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        int[] s = decode(raw).codePoints().toArray();
        int n = s.length;
        System.out.print(encode(new int[] {s[n - 1], ' ', s[n - 2]}) + "\n");
    }
}
